insert into public.listings (name, kind, url, tagline, description, tags, credit_balance_usd, status)
values
('Linear', 'startup', 'https://linear.app', 'Issue tracking built for high-performance software teams', 'Linear is the issue tracker used by product and engineering teams that want speed, keyboard-first workflows, and clean roadmaps. A good partner when a builder needs real project ops after the first users show up.', '{seed_test}', 20, 'active'),
('Notion', 'startup', 'https://www.notion.so', 'One workspace for docs, wikis, and light project ops', 'Notion is the all-in-one workspace for docs, wikis, and lightweight CRM. Useful when a young company still keeps process in chat and needs a shared source of truth.', '{seed_test}', 20, 'active'),
('Figma', 'startup', 'https://www.figma.com', 'Collaborative interface design for product teams', 'Figma is the design tool for interfaces, prototypes, and design systems. The right partner when a site can generate UI but still needs craft, brand, and a system designers can own.', '{seed_test}', 20, 'active'),
('Framer', 'startup', 'https://www.framer.com', 'Design and publish production marketing sites', 'Framer lets designers ship marketing sites with real interactions, CMS, and SEO. Complements an app builder when the product exists but the public site still looks like a placeholder.', '{seed_test}', 20, 'active'),
('Webflow', 'startup', 'https://webflow.com', 'Visual development for marketing sites and CMS', 'Webflow is a visual builder for marketing sites, landing pages, and CMS. A growth partner when the product is ready but acquisition pages need structure, speed, and editorial control.', '{seed_test}', 20, 'active'),
('Vercel', 'startup', 'https://vercel.com', 'Frontend cloud for shipping Next.js and modern web apps', 'Vercel hosts and ships frontend apps with preview URLs, edge, and analytics. Complements a generated app that now needs reliable deploys, previews, and a path to production.', '{seed_test}', 20, 'active'),
('Stripe', 'startup', 'https://stripe.com', 'Payments infrastructure for internet businesses', 'Stripe is the payments stack for checkout, billing, and invoicing. The partner you add when a product can be used but cannot yet collect money cleanly.', '{seed_test}', 20, 'active'),
('Resend', 'startup', 'https://resend.com', 'Email API for transactional product mail', 'Resend is an email API for transactional and product mail with a simple developer workflow. Helps a new app send onboarding, receipts, and magic links without standing up mail ops.', '{seed_test}', 20, 'active'),
('Clerk', 'startup', 'https://clerk.com', 'Authentication and user management for modern apps', 'Clerk ships auth, orgs, and user management with drop-in components. A fit when an AI-built app still has a thin login story or no multiplayer accounts.', '{seed_test}', 20, 'active'),
('PostHog', 'startup', 'https://posthog.com', 'Product analytics, session replay, and feature flags', 'PostHog is an open product-analytics suite with replay, flags, and funnels. The partner for a new product that ships features but cannot see who converts or where they drop.', '{seed_test}', 20, 'active'),
('Amplitude', 'startup', 'https://amplitude.com', 'Product analytics to find what drives retention', 'Amplitude helps product teams measure journeys, retention, and experiments. Complements a builder tool when usage exists but nobody knows which path turns a visitor into a customer.', '{seed_test}', 20, 'active'),
('Mixpanel', 'startup', 'https://mixpanel.com', 'Event analytics for self-serve product teams', 'Mixpanel is event analytics for self-serve product teams. Useful when a startup needs to prove activation instead of guessing from pageviews.', '{seed_test}', 20, 'active'),
('Intercom', 'startup', 'https://www.intercom.com', 'AI customer service and in-product messaging', 'Intercom is the inbox and messenger for support and onboarding. A growth partner when the product is live but there is no place for users to get unstuck.', '{seed_test}', 20, 'active'),
('Crisp', 'startup', 'https://crisp.chat', 'Shared inbox and live chat for small teams', 'Crisp is a shared inbox and live chat for lean teams. Helps an early site capture leads and questions instead of losing them on a static landing page.', '{seed_test}', 20, 'active'),
('Cal.com', 'startup', 'https://cal.com', 'Open scheduling infrastructure for meetings', 'Cal.com is open scheduling for sales, hiring, and success calls. Complements a product that wants inbound demos but still says “email us” on the site.', '{seed_test}', 20, 'active'),
('Loom', 'startup', 'https://www.loom.com', 'Async video for explaining product and process', 'Loom is async video for walkthroughs, sales, and support. A partner when a complex product needs human explanation faster than docs.', '{seed_test}', 20, 'active'),
('Granola', 'startup', 'https://www.granola.ai', 'AI notepad for meetings that become next steps', 'Granola turns meeting notes into structured follow-ups. Useful for founders doing many customer calls who need signal, not another recorder.', '{seed_test}', 20, 'active'),
('Cursor', 'startup', 'https://cursor.com', 'AI code editor for teams shipping in production', 'Cursor is an AI-native code editor for people who still own the codebase. Complements a generated app when the next step is real engineering, refactors, and review.', '{seed_test}', 20, 'active'),
('Replit', 'startup', 'https://replit.com', 'Cloud IDE and agents to build and host software', 'Replit is a cloud IDE and agent platform to build and host software in the browser. Adjacent to app builders; better as a place to keep iterating once a prototype exists.', '{seed_test}', 20, 'active'),
('Bolt', 'startup', 'https://bolt.new', 'Prompt-to-app builder for full-stack prototypes', 'Bolt generates full-stack apps from prompts in the browser. Similar motion to other AI builders, so it is a peer more than a complement unless the visitor needs a different stack.', '{seed_test}', 20, 'active'),
('v0', 'startup', 'https://v0.dev', 'AI UI generation for React and shadcn interfaces', 'v0 generates React interfaces from prompts. A complement when someone can ship logic but the UI still looks unfinished, not a clone of a full app builder.', '{seed_test}', 20, 'active'),
('Railway', 'startup', 'https://railway.app', 'Deploy backends, databases, and workers without ops theater', 'Railway deploys backends, databases, and workers from git. Helps when a generated frontend needs a real API, cron, or Postgres that is not a toy.', '{seed_test}', 20, 'active'),
('Render', 'startup', 'https://render.com', 'Cloud for web services, workers, and Postgres', 'Render hosts web services, workers, and Postgres with simple pricing. A production partner after the first prototype leaves the builder sandbox.', '{seed_test}', 20, 'active'),
('Neon', 'startup', 'https://neon.tech', 'Serverless Postgres with branching for developers', 'Neon is serverless Postgres with branching and scale-to-zero. Complements an app that needs a real database without standing up a cluster.', '{seed_test}', 20, 'active'),
('Convex', 'startup', 'https://www.convex.dev', 'Reactive backend for products that stay in sync', 'Convex is a reactive backend for TypeScript apps that need live data. A fit when a generated UI still has no durable multiplayer state.', '{seed_test}', 20, 'active'),
('Plaid', 'startup', 'https://plaid.com', 'Bank connections and financial data APIs', 'Plaid connects apps to bank accounts and financial data. The partner when a product wants money movement, KYC, or balances without becoming a bank.', '{seed_test}', 20, 'active'),
('Mercury', 'startup', 'https://mercury.com', 'Banking built for startups', 'Mercury is a bank for startups: accounts, cards, and treasury. Complements a company that can invoice but still mixes founder and company money.', '{seed_test}', 20, 'active'),
('Ramp', 'startup', 'https://ramp.com', 'Corporate cards and spend control for growing teams', 'Ramp issues cards and controls spend with receipts and policy. Useful once a team starts paying tools and contractors without a finance hire.', '{seed_test}', 20, 'active'),
('Gusto', 'startup', 'https://gusto.com', 'Payroll, benefits, and HR for small companies', 'Gusto runs payroll, benefits, and HR for small US companies. The partner after the first hire, when 1099 chaos becomes a risk.', '{seed_test}', 20, 'active'),
('Deel', 'startup', 'https://www.deel.com', 'Global payroll and contractor compliance', 'Deel hires and pays people in many countries with compliance baked in. Complements a product company that wants remote talent without a legal team.', '{seed_test}', 20, 'active'),
('Carta', 'startup', 'https://carta.com', 'Cap tables, equity, and fundraising ops', 'Carta is the cap table and equity platform for private companies. A partner when founders still track ownership in a spreadsheet.', '{seed_test}', 20, 'active'),
('Clerky', 'startup', 'https://www.clerky.com', 'Startup legal paperwork for formation and fundraising', 'Clerky automates formation, SAFEs, and hiring docs for startups. Complements a live product that still has no clean company or IP assignment.', '{seed_test}', 20, 'active'),
('beehiiv', 'startup', 'https://www.beehiiv.com', 'Newsletter platform built for growth and monetization', 'beehiiv is a newsletter platform with recommendations, ads, and paid tiers. A distribution partner when a product has a story but no owned audience.', '{seed_test}', 20, 'active'),
('Kit', 'startup', 'https://kit.com', 'Email marketing for creators and indie businesses', 'Kit (formerly ConvertKit) is email marketing for creators. Helps a founder turn site visitors into a list instead of relying on one launch post.', '{seed_test}', 20, 'active'),
('Apollo.io', 'startup', 'https://www.apollo.io', 'B2B contact data and outbound sequences', 'Apollo is a B2B database and sequencer for outbound. Complements a product with a landing page but no repeatable way to book meetings.', '{seed_test}', 20, 'active'),
('Clay', 'startup', 'https://www.clay.com', 'Enrichment and GTM workflows on top of your data', 'Clay enriches leads and runs go-to-market workflows across tools. A growth partner when the founder is still doing research one LinkedIn tab at a time.', '{seed_test}', 20, 'active'),
('Attio', 'startup', 'https://attio.com', 'CRM that starts from your relationships, not a pipeline template', 'Attio is a flexible CRM built on real relationship data. Useful when a team outgrows a spreadsheet but is not ready for enterprise Salesforce.', '{seed_test}', 20, 'active'),
('Typeform', 'startup', 'https://www.typeform.com', 'Conversational forms for research and lead capture', 'Typeform makes forms that feel like a conversation. Complements a site that needs research, waitlists, or onboarding questions without a custom flow.', '{seed_test}', 20, 'active'),
('Tally', 'startup', 'https://tally.so', 'Free, Notion-like forms for fast intake', 'Tally is a free form builder with a Notion-like editor. A simple partner for waitlists, applications, and feedback when the product page has no capture.', '{seed_test}', 20, 'active'),
('Relume', 'startup', 'https://www.relume.io', 'AI sitemaps and Webflow components for marketing sites', 'Relume generates sitemaps, wireframes, and Webflow libraries. Complements an app company whose marketing site is still a single hero and a vague CTA.', '{seed_test}', 20, 'active'),
('Ahrefs', 'startup', 'https://ahrefs.com', 'SEO data for keywords, links, and content gaps', 'Ahrefs is the SEO toolkit for keywords, backlinks, and content gaps. A growth partner when a product has users from Twitter but no search demand plan.', '{seed_test}', 20, 'active'),
('Semrush', 'startup', 'https://www.semrush.com', 'SEO, ads, and competitive research in one suite', 'Semrush covers SEO, PPC, and competitor research. Complements a founder who is guessing channels instead of seeing who already ranks.', '{seed_test}', 20, 'active'),
('ElevenLabs', 'startup', 'https://elevenlabs.io', 'AI voice for products, media, and support', 'ElevenLabs is AI voice for products, agents, and media. A fit when a company wants audio UX, localization, or voice agents without a studio.', '{seed_test}', 20, 'active'),
('Descript', 'startup', 'https://www.descript.com', 'Edit video and podcasts like a document', 'Descript edits video and podcasts from a transcript. Complements a product that needs explainers and founder-led content without a production team.', '{seed_test}', 20, 'active'),
('Runway', 'startup', 'https://runwayml.com', 'Generative video tools for teams making visual stories', 'Runway is a generative video suite for ads, story, and product shots. A creative partner when the site still uses stock and needs motion to sell the product.', '{seed_test}', 20, 'active'),
('Mux', 'startup', 'https://www.mux.com', 'Video infrastructure for apps that need playback at scale', 'Mux is video infrastructure: encode, stream, and analytics. Complements a product that wants in-app video without becoming a streaming company.', '{seed_test}', 20, 'active'),
('Raycast', 'consumer_app', 'https://www.raycast.com', 'Launcher and AI commands for people who live in the keyboard', 'Raycast is a macOS launcher with AI, snippets, and team extensions. Adjacent productivity software more than a growth partner, unless the visitor sells to the same power users.', '{seed_test}', 20, 'active'),
('Pitch', 'startup', 'https://pitch.com', 'Collaborative presentations for modern teams', 'Pitch is a collaborative presentation tool for product and sales decks. Complements a founder who still pitches from a Notion doc or a stale Keynote.', '{seed_test}', 20, 'active'),
('Gamma', 'startup', 'https://gamma.app', 'AI decks and docs that look finished fast', 'Gamma generates decks and docs from outlines. A partner for fundraising or sales when the product is real but the story is still a messy Google Doc.', '{seed_test}', 20, 'active'),
('Superhuman', 'consumer_app', 'https://superhuman.com', 'Fast email for people who live in their inbox', 'Superhuman is a fast email client for people who treat inbox as the OS. More complementary for operators drowning in mail than for a product that needs distribution.', '{seed_test}', 20, 'active');
